<script setup>
defineProps({ analytics: { type: Object, default: () => ({ summary: {}, daily_volume: [], sla_breaches: [] }) } });
const max = (items, key) => Math.max(1, ...items.map((item) => item[key] || 0));
</script>

<template>
  <div class="space-y-6"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><div v-for="item in [{ label: 'Total orders', value: analytics.summary.total_orders }, { label: 'Delivery rate', value: `${analytics.summary.delivery_rate || 0}%` }, { label: 'Delivered', value: analytics.summary.delivered }, { label: 'Sorting breaches', value: analytics.summary.sorting_breaches }, { label: 'Final-mile breaches', value: analytics.summary.final_mile_breaches }]" :key="item.label" class="border border-slate-200 bg-white p-4 shadow-sm"><p class="text-xs font-bold uppercase tracking-wider text-slate-500">{{ item.label }}</p><p class="mt-2 text-3xl font-black">{{ item.value ?? 0 }}</p></div></div><div class="grid gap-6 lg:grid-cols-2"><section class="border border-slate-200 bg-white p-5 shadow-sm"><h2 class="text-lg font-bold">Daily volume trend</h2><div class="mt-6 flex h-52 items-end gap-2 border-b border-l border-slate-200 px-3 pb-0"><div v-for="day in analytics.daily_volume" :key="day.date" class="group flex flex-1 flex-col justify-end gap-2" :title="`${day.date}: ${day.volume} orders`"><div class="bg-teal-600 transition group-hover:bg-teal-400" :style="{ height: `${(day.volume / max(analytics.daily_volume, 'volume')) * 100}%`, minHeight: '4px' }" /><span class="hidden -rotate-45 origin-top-left whitespace-nowrap text-[10px] text-slate-400 sm:block">{{ day.date.slice(5) }}</span></div><p v-if="!analytics.daily_volume?.length" class="m-auto text-sm text-slate-400">No volume data for this range.</p></div></section><section class="border border-slate-200 bg-white p-5 shadow-sm"><h2 class="text-lg font-bold">SLA breach classification</h2><div class="mt-6 space-y-5"><div><div class="flex justify-between text-sm font-semibold"><span>Sorting delays</span><span>{{ analytics.summary.sorting_breaches || 0 }}</span></div><div class="mt-2 h-3 bg-slate-100"><div class="h-3 bg-amber-400" :style="{ width: `${Math.min(100, (analytics.summary.sorting_breaches || 0) / Math.max(1, analytics.summary.total_orders || 1) * 100)}%` }" /></div></div><div><div class="flex justify-between text-sm font-semibold"><span>Final-mile delays</span><span>{{ analytics.summary.final_mile_breaches || 0 }}</span></div><div class="mt-2 h-3 bg-slate-100"><div class="h-3 bg-red-500" :style="{ width: `${Math.min(100, (analytics.summary.final_mile_breaches || 0) / Math.max(1, analytics.summary.total_orders || 1) * 100)}%` }" /></div></div></div><div class="mt-8 max-h-36 overflow-y-auto divide-y divide-slate-100"><div v-for="breach in analytics.sla_breaches" :key="breach.order_id" class="flex justify-between py-2 text-sm"><span class="font-mono">{{ breach.awb_number }}</span><span class="font-bold capitalize text-red-700">{{ breach.status.replace('_', ' ') }}</span></div><p v-if="!analytics.sla_breaches?.length" class="py-4 text-sm text-slate-400">No SLA breaches recorded.</p></div></section></div></div>
